struct EventBuilder {
  typedef Event Table;
  flatbuffers::FlatBufferBuilder &fbb_;
  flatbuffers::uoffset_t start_;
  void add_seq(uint64_t seq) {
    fbb_.AddElement<uint64_t>(Event::VT_SEQ, seq, 0);
  }
  void add_ts(uint64_t ts) {
    fbb_.AddElement<uint64_t>(Event::VT_TS, ts, 0);
  }
  void add_type_type(exc::wire::EventType type_type) {
    fbb_.AddElement<uint8_t>(Event::VT_TYPE_TYPE, static_cast<uint8_t>(type_type), 0);
  }
  void add_type(flatbuffers::Offset<void> type) {
    fbb_.AddOffset(Event::VT_TYPE, type);
  }
  explicit EventBuilder(flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  flatbuffers::Offset<Event> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = flatbuffers::Offset<Event>(end);
    return o;
  }
};

inline flatbuffers::Offset<Event> CreateEvent(
    flatbuffers::FlatBufferBuilder &_fbb,
    uint64_t seq = 0,
    uint64_t ts = 0,
    exc::wire::EventType type_type = exc::wire::EventType_NONE,
    flatbuffers::Offset<void> type = 0) {
  EventBuilder builder_(_fbb);
  builder_.add_ts(ts);
  builder_.add_seq(seq);
  builder_.add_type(type);
  builder_.add_type_type(type_type);
  return builder_.Finish();
}

inline bool VerifyEventType(flatbuffers::Verifier &verifier, const void *obj, EventType type) {
  switch (type) {
    case EventType_NONE: {
      return true;
    }
    case EventType_OrderNew: {
      auto ptr = reinterpret_cast<const exc::wire::OrderNew *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case EventType_OrderCancel: {
      auto ptr = reinterpret_cast<const exc::wire::OrderCancel *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case EventType_TradeFill: {
      auto ptr = reinterpret_cast<const exc::wire::TradeFill *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case EventType_BookSnapshot: {
      auto ptr = reinterpret_cast<const exc::wire::BookSnapshot *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case EventType_TimeTick: {
      auto ptr = reinterpret_cast<const exc::wire::TimeTick *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case EventType_OrderAmend: {
      auto ptr = reinterpret_cast<const exc::wire::OrderAmend *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case EventType_OcoLink: {
      auto ptr = reinterpret_cast<const exc::wire::OcoLink *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case EventType_AuctionEvent: {
      auto ptr = reinterpret_cast<const exc::wire::AuctionEvent *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyEventTypeVector(flatbuffers::Verifier &verifier, const flatbuffers::Vector<flatbuffers::Offset<void>> *values, const flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyEventType(
        verifier,  values->Get(i), types->GetEnum<EventType>(i))) {
      return false;
    }
  }
  return true;
}

inline const exc::wire::Event *GetEvent(const void *buf) {
  return flatbuffers::GetRoot<exc::wire::Event>(buf);
}

inline const exc::wire::Event *GetSizePrefixedEvent(const void *buf) {
  return flatbuffers::GetSizePrefixedRoot<exc::wire::Event>(buf);
}

inline bool VerifyEventBuffer(
    flatbuffers::Verifier &verifier) {
  return verifier.VerifyBuffer<exc::wire::Event>(nullptr);
}

inline bool VerifySizePrefixedEventBuffer(
    flatbuffers::Verifier &verifier) {
  return verifier.VerifySizePrefixedBuffer<exc::wire::Event>(nullptr);
}

inline void FinishEventBuffer(
    flatbuffers::FlatBufferBuilder &fbb,
    flatbuffers::Offset<exc::wire::Event> root) {
  fbb.Finish(root);
}

inline void FinishSizePrefixedEventBuffer(
    flatbuffers::FlatBufferBuilder &fbb,
    flatbuffers::Offset<exc::wire::Event> root) {
  fbb.FinishSizePrefixed(root);
}

